mapper.select:
SELECT COUNT(*) FROM t_test_drive WHERE owner_id=#{targetUserId} AND id<>#{excludedId}
  AND status IN ('PENDING_CONFIRM','SCHEDULED','RESCHEDULED','CHECKED_IN')
  AND planned_start_time < #{endTime} AND planned_end_time > #{startTime}

SELECT event.id,event.operation_id,event.action,event.user_id,event.employee_id,event.before_value,event.after_value,event.reason,
  event.operator_id,COALESCE(NULLIF((SELECT MAX(log_entry.user_name) FROM t_operation_log log_entry WHERE log_entry.request_id=event.request_id),''),'系统') AS operator_name,
  NULL AS operator_employee_no,event.occurred_time
FROM t_user_lifecycle_event event
WHERE event.user_id=#{userId}
AND event.occurred_time>=#{startTime}
AND event.occurred_time<=#{endTime}
ORDER BY event.occurred_time DESC,event.id DESC
